[
  {
    "name": "read",
    "description": "读取工作区内文件内容；可用 start_line/end_line 读取指定行区间（大文件分片阅读）",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "相对工作区根的路径"
        },
        "start_line": {
          "type": "number",
          "description": "起始行号（从 1 起，可选）"
        },
        "end_line": {
          "type": "number",
          "description": "结束行号（含，可选）"
        }
      },
      "required": [
        "path"
      ]
    }
  },
  {
    "name": "grep",
    "description": "在工作区文件中按正则搜索，输出 文件:行号: 内容",
    "parameters": {
      "type": "object",
      "properties": {
        "pattern": {
          "type": "string",
          "description": "正则表达式"
        },
        "path": {
          "type": "string",
          "description": "起始目录（默认工作区根）"
        },
        "glob": {
          "type": "string",
          "description": "文件名通配过滤，如 *.ts"
        },
        "case_sensitive": {
          "type": "boolean",
          "description": "大小写敏感（默认 true）"
        }
      },
      "required": [
        "pattern"
      ]
    }
  },
  {
    "name": "find",
    "description": "按文件名通配符（* / ?）查找文件与目录",
    "parameters": {
      "type": "object",
      "properties": {
        "pattern": {
          "type": "string",
          "description": "文件名通配符，如 *.ts"
        },
        "path": {
          "type": "string",
          "description": "起始目录（默认工作区根）"
        }
      },
      "required": [
        "pattern"
      ]
    }
  },
  {
    "name": "ls",
    "description": "列出目录内容（目录名带 / 后缀）",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "目录路径（默认工作区根）"
        }
      }
    }
  },
  {
    "name": "git_status",
    "description": "查看 Git 工作区状态（git status --short）：改/删/暂存文件清单",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "name": "git_diff",
    "description": "查看 Git diff（未暂存默认；staged=true 看已暂存）。可按路径过滤",
    "parameters": {
      "type": "object",
      "properties": {
        "path": {
          "type": "string",
          "description": "限定查看此路径的 diff（可选）"
        },
        "staged": {
          "type": "boolean",
          "description": "true 查看已暂存（--cached）变更；默认 false"
        }
      }
    }
  },
  {
    "name": "git_log",
    "description": "查看 Git 提交历史（一行为一条：hash + 主题）",
    "parameters": {
      "type": "object",
      "properties": {
        "limit": {
          "type": "number",
          "description": "最近几条提交（默认 20，上限 100）"
        }
      }
    }
  },
  {
    "name": "git_branch",
    "description": "列出 Git 本地分支（按最近提交时间倒序）",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  }
]
